    {
      "name": "Asymptotics.IsBigOWith.of_pow",
      "module_name": "Mathlib.Analysis.Asymptotics.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {R : Type u_13} [inst : SeminormedRing R] {S : Type u_17} [inst_1 : NormedRing S] [NormMulClass S]\n  {c c' : ℝ} {l : Filter α} [NormOneClass S] {n : ℕ} {f : α → S} {g : α → R},\n  Asymptotics.IsBigOWith c l (f ^ n) (g ^ n) → n ≠ 0 → c ≤ c' ^ n → 0 ≤ c' → Asymptotics.IsBigOWith c' l f g"
    },
