    },
    {
      "name": "Asymptotics.IsBigOWith.rpow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Asymptotics",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {r c : ℝ} {l : Filter α} {f g : α → ℝ},\n  Asymptotics.IsBigOWith c l f g →\n    0 ≤ c → 0 ≤ r → 0 ≤ᶠ[l] g → Asymptotics.IsBigOWith (c ^ r) l (fun x => f x ^ r) fun x => g x ^ r"
    },
